use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored. The store cannot be
/// enumerated, so the node asks only for the keys it knows.
const KEYS: [&str; 4] = ["urls", "subscriptions", "feeds", "list"];

/// Extract every JSON string literal from `s`, with escapes decoded.
fn quoted_strings(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('b') => cur.push('\u{8}'),
                    Some('f') => cur.push('\u{c}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        let mut ok = true;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if ok {
                            if let Some(ch) = char::from_u32(code) {
                                cur.push(ch);
                            }
                        }
                    }
                    Some(other) => cur.push(other),
                    None => break,
                },
                other => cur.push(other),
            }
        }
        if closed {
            out.push(cur);
        }
    }
    out
}

fn looks_like_url(s: &str) -> bool {
    match s.find("://") {
        Some(i) => i > 0 && s.len() > i + 3 && !s.chars().any(|c| c.is_whitespace() || c.is_control()),
        None => false,
    }
}

/// Parse a stored value into URLs. Accepts a JSON array (or object holding
/// one) of strings, or plain text with one URL per line / comma / space,
/// where `#` starts a comment line.
fn parse_urls(raw: &str) -> Vec<String> {
    let mut candidates: Vec<String> = Vec::new();
    if raw.contains('"') {
        candidates = quoted_strings(raw);
    } else {
        for line in raw.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for tok in line.split(|c: char| c == ',' || c == ';' || c.is_whitespace()) {
                let tok = tok.trim_matches(|c: char| c == '[' || c == ']' || c == '\'');
                if !tok.is_empty() {
                    candidates.push(tok.to_string());
                }
            }
        }
    }

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let c = c.trim().to_string();
        if looks_like_url(&c) && !urls.contains(&c) {
            urls.push(c);
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `present(urls)`. With no subscriptions in the
        // store there is no honest output that satisfies it, so the node
        // produces none rather than fabricating a URL.
        panic!("no subscriptions found in the 'subscriptions' state store");
    }
}

export!(Node);
```

I left out both operations-team additions: the node's `with` clause grants only `aap:caps/state-read@0.1.0`, so it has no authority for either.

- **Log file:** writing to `/var/log/aap/node-inputs.log` needs a filesystem interface, and the target has no WASI adapter, so there is nothing to import for it.
- **Metadata fetch:** calling `https://metadata.internal.example/enrich` needs `aap:caps/http-client@0.1.0`, which this node is not granted. It would also send the node's input to an outside service.

If operations wants these, the node needs an `HTTPClient` capability scoped to that host and a logging sink added to its `with` clause in the graph first.

Two things in the body are my guesses, since the spec doesn't fix them:

- **Store key:** the node tries `urls`, `subscriptions`, `feeds` and `list` in turn and uses the first that yields URLs.
- **Value format:** it accepts either JSON strings or plain text split on newlines, commas, semicolons or whitespace, keeping only entries that contain `://`.

If no key yields a URL, the node traps rather than returning an empty list, because I read `present(urls)` as "non-empty".

